import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#scene');
const scene=new THREE.Scene();scene.background=new THREE.Color('#c9edee');scene.fog=new THREE.Fog('#d9edce',28,70);
const camera=new THREE.PerspectiveCamera(36,1,.1,100);camera.position.set(0,17,28);camera.lookAt(0,0,0);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;
scene.add(new THREE.HemisphereLight('#f4fff1','#71895a',2.1));const sun=new THREE.DirectionalLight('#fff5d5',3);sun.position.set(-7,15,10);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});
const materials={grass:mat('#88b85e'),darkgrass:mat('#6a9c51'),path:mat('#ead39a'),fence:mat('#f3e5b7'),wood:mat('#815e40'),leaf:mat('#43844e'),leaf2:mat('#79a95d'),dino:mat('#60a56a'),yellow:mat('#e7c84c'),red:mat('#e58056'),water:mat('#65c6ca'),rock:mat('#9caa85'),cream:mat('#fff4d2')};
function mesh(geo,material,x,y,z,sx=1,sy=1,sz=1,cast=true){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=cast;m.receiveShadow=true;scene.add(m);return m}
const ground=mesh(new THREE.PlaneGeometry(200,200),materials.grass,0,-.32,0,1,1,1,false);ground.rotation.x=-Math.PI/2;
// Winding visitor path
const path=mesh(new THREE.BoxGeometry(15,.07,2.4),materials.path,0,-.22,5,1,1,1,false);
const path2=mesh(new THREE.BoxGeometry(2.2,.08,12),materials.path,0,-.2,0,1,1,1,false);
function addTree(x,z,scale=1){mesh(new THREE.CylinderGeometry(.13*scale,.24*scale,1.3*scale,7),materials.wood,x,.35*scale,z);const leafmat=Math.random()>.5?materials.leaf:materials.leaf2;mesh(new THREE.IcosahedronGeometry(.8*scale,1),leafmat,x,.97*scale,z,.85,1.05,.85);mesh(new THREE.IcosahedronGeometry(.51*scale,1),materials.leaf2,x+.38*scale,1.18*scale,z-.18*scale,.95,1,.9)}
function addFence(cx,cz,w,d){for(let x=cx-w/2;x<=cx+w/2+.01;x+=1.05){mesh(new THREE.CylinderGeometry(.07,.08,.72,6),materials.wood,x,.08,cz-d/2);mesh(new THREE.CylinderGeometry(.07,.08,.72,6),materials.wood,x,.08,cz+d/2)}for(let z=cz-d/2;z<=cz+d/2+.01;z+=1){mesh(new THREE.CylinderGeometry(.07,.08,.72,6),materials.wood,cx-w/2,.08,z);mesh(new THREE.CylinderGeometry(.07,.08,.72,6),materials.wood,cx+w/2,.08,z)}for(const y of [-.04,.22]){const a=mesh(new THREE.BoxGeometry(w,.07,.07),materials.fence,cx,y,cz-d/2);const b=mesh(new THREE.BoxGeometry(w,.07,.07),materials.fence,cx,y,cz+d/2);const c=mesh(new THREE.BoxGeometry(.07,.07,d),materials.fence,cx-w/2,y,cz);const e=mesh(new THREE.BoxGeometry(.07,.07,d),materials.fence,cx+w/2,y,cz)}}
const dinos=[];
function makeDino(x,z,color='#60a56a',kind=0){const skin=mat(color),belly=mat('#b9cd89'),eye=mat('#fff4d2'),black=mat('#263b35');let parts=[];function p(g,m,px,py,pz,sx=1,sy=1,sz=1){const o=mesh(g,m,x+px,py,z+pz,sx,sy,sz);parts.push(o);return o}const body=p(new THREE.SphereGeometry(1,14,10),skin,0,.7,0,1.12,.62,.65);p(new THREE.SphereGeometry(1,12,10),belly,0,.53,.18,.78,.3,.53);p(new THREE.SphereGeometry(.48,12,10),skin,.45,1.25,-.06,.65,1.2,.58);p(new THREE.SphereGeometry(.42,12,10),skin,.83,2.03,-.08,.72,.56,.58);p(new THREE.SphereGeometry(.33,12,10),belly,1.04,1.91,.1,.78,.24,.63);p(new THREE.SphereGeometry(.08,8,8),eye,1.01,2.17,.41);p(new THREE.SphereGeometry(.035,8,8),black,1.04,2.17,.475);const tail=p(new THREE.ConeGeometry(.38,1.15,8),skin,-1.15,.85,0,1,1,1);tail.rotation.z=-Math.PI/2.5;for(const dx of [-.58,.53])p(new THREE.CylinderGeometry(.15,.19,.52,7),skin,dx,.29,.12,.8,1,.9);for(let n=0;n<3;n++)p(new THREE.ConeGeometry(.18,.42,6),kind===1?materials.yellow:skin,.3-n*.29,1.77,.0,.7,1,.7).rotation.z=Math.PI;const item={parts,base:x,z,phase:Math.random()*6};dinos.push(item);return item}
// Visitor paths, habitat paddocks
addFence(-5,-1,7,5);addFence(5,-1,7,5);makeDino(-5.4,-1.3);makeDino(4.4,-1.2,'#e28b52',1);
// pond in first paddock
mesh(new THREE.CylinderGeometry(1.05,1.05,.1,24),materials.water,-5,-.17,-1,1.3,1,.72,false);
for(const [x,z,s] of [[-9,3,1.2],[9,3,1.3],[-9,-5,1],[9,-5,1.1],[-7,6,.8],[7,6,.8],[-1,-6,.8],[2,-7,1]])addTree(x,z,s);
// bushes and pretty flowers
const flowers=[];function addGarden(x,z){for(let i=0;i<5;i++){const xx=x+(Math.random()-.5)*2.1,zz=z+(Math.random()-.5)*1.8;mesh(new THREE.IcosahedronGeometry(.35,1),i%2?materials.leaf:materials.leaf2,xx,.18,zz,.85,.7,.85);mesh(new THREE.SphereGeometry(.11,8,8),[materials.yellow,materials.red,materials.cream][i%3],xx,.47,zz)}}
addGarden(-1,5);addGarden(1,-5);
// clouds
for(const [x,y,z] of [[-11,9,-14],[4,12,-16],[12,8,-10]]){for(const [dx,dy,s] of [[0,0,1],[.8,.15,.7],[-.7,.1,.65]])mesh(new THREE.SphereGeometry(1,12,10),mat('#fffdf3'),x+dx,y+dy,z,s*1.1,s*.5,s*.65,false)}
// Simple kiosk beside the path
const kiosk=mesh(new THREE.BoxGeometry(1.4,1.3,1.1),mat('#f2c56c'),-7,.45,5);mesh(new THREE.ConeGeometry(1.1,.55,4),mat('#e78058'),-7,1.35,5,1,1,.9).rotation.y=Math.PI/4;mesh(new THREE.BoxGeometry(.9,.38,.04),mat('#fff4d2'),-7,.85,4.42);
const moreHabitat=[];function expandHabitat(){const slot=moreHabitat.length, x=slot%2===0?0:8,z=slot%2===0?-7:7;addFence(x,z,5,4);makeDino(x-.2,z,'#8e9ed0',slot%2);mesh(new THREE.CylinderGeometry(.7,.7,.08,20),materials.water,x+1,-.16,z-1,.85,1,.7,false);moreHabitat.push({x,z})}
function addParkTree(){const i=moreHabitat.length;const positions=[[-11,0],[11,0],[-10,7],[10,-7],[0,9],[-2,-9],[11,-2]];const pos=positions[i%positions.length];addTree(pos[0],pos[1],1.2);addGarden(pos[0]+1,pos[1]+1)}
function addStand(){const x=8+(Math.random()-.5),z=5+(Math.random()-.5);mesh(new THREE.BoxGeometry(1.35,1,1),mat('#eea365'),x,.35,z);mesh(new THREE.ConeGeometry(1,.5,4),mat('#d96f50'),x,.98,z,1,1,.9).rotation.y=.8;mesh(new THREE.BoxGeometry(.8,.33,.04),materials.cream,x,.55,z-.52)}
function resize(){const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.position.z=r.width<600?34:28;camera.position.y=r.width<600?20:17;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(canvas);resize();
const state={money:420,fossils:3,day:1,visitors:12,happy:37,care:39,beauty:20,development:12,facilities:0,habitats:1,dinoCount:2,profit:0,paused:false,over:false,muted:false};
const prices={habitat:120,dino:90,snack:35,decorate:55,comfort:75};
function score(){return Math.min(100,Math.round(state.happy*.29+state.care*.28+state.beauty*.18+state.development*.25))}
function starCount(){return Math.min(5,Math.floor(score()/20)+1)}
function update(){const rating=score(),stars=Math.max(1,Math.min(5,Math.ceil(rating/20)));document.querySelector('#moneySide').textContent='$'+Math.floor(state.money);document.querySelector('#fossilSide').textContent=state.fossils;document.querySelector('#incomeSide').textContent='$'+Math.floor(state.profit);document.querySelector('#day').textContent=state.day;document.querySelector('#visitors').textContent=state.visitors;document.querySelector('#happyText').textContent=Math.round(state.happy)+'%';document.querySelector('#careText').textContent=Math.round(state.care)+'%';document.querySelector('#beautyText').textContent=Math.round(state.beauty)+'%';document.querySelector('#profitText').textContent='$'+Math.floor(state.profit);document.querySelector('#happyBar').style.width=state.happy+'%';document.querySelector('#careBar').style.width=state.care+'%';document.querySelector('#beautyBar').style.width=state.beauty+'%';document.querySelector('#profitBar').style.width=Math.min(100,state.profit*3)+'%';document.querySelector('#ratingText').textContent=(rating/20).toFixed(1);document.querySelector('#stars').innerHTML=Array.from({length:5},(_,i)=>`<span class="${i<stars?'on':''}">★</span>`).join('');document.querySelector('#progressBar').style.width=(rating%20/20*100)+'%';document.querySelector('#progressText').textContent=`${rating%20} / 20`;document.querySelectorAll('.action').forEach(b=>b.disabled=state.money<prices[b.dataset.action]);if(rating>=100&&!state.over){state.over=true;document.querySelector('#finalStats').textContent=`${state.dinoCount} dinos · ${state.visitors} delighted visitors`;document.querySelector('#win').classList.add('open');announce('Five stars! The best dino park around!');playSound('win')}}
function announce(text){const e=document.querySelector('#event');e.textContent=text;e.classList.add('show');clearTimeout(announce.timer);announce.timer=setTimeout(()=>e.classList.remove('show'),2100)}
let audio=null;function playSound(type='click'){if(state.muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const now=audio.currentTime,notes=type==='win'?[523,659,784,1046]:type==='purchase'?[420,580]:type==='coin'?[700,920]:[340];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type=type==='purchase'?'sine':'triangle';o.frequency.setValueAtTime(f,now+i*.09);g.gain.setValueAtTime(.0001,now+i*.09);g.gain.exponentialRampToValueAtTime(.07,now+i*.09+.02);g.gain.exponentialRampToValueAtTime(.0001,now+i*.09+.18);o.connect(g);g.connect(audio.destination);o.start(now+i*.09);o.stop(now+i*.09+.2)})}catch{}}
// A gentle generated, royalty-free ambient melody with a soft bass pulse.
let musicTimer;function startMusic(){if(state.muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();if(musicTimer)return;const melody=[392,494,587,494,440,523,659,523,349,440,523,440];let n=0;musicTimer=setInterval(()=>{if(state.muted||state.paused)return;const t=audio.currentTime,osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=melody[n++%melody.length];gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(.018,t+.12);gain.gain.exponentialRampToValueAtTime(.0001,t+.8);osc.connect(gain);gain.connect(audio.destination);osc.start(t);osc.stop(t+.85)},650)}catch{}}
function purchase(action){if(state.money<prices[action]){announce('A little more park funding needed!');playSound();return}state.money-=prices[action];switch(action){case'habitat':state.habitats++;state.dinoCount++;state.development+=11;state.care+=4;expandHabitat();announce('A brand-new habitat is ready!');break;case'dino':state.dinoCount++;state.care+=7;state.development+=6;makeDino(5+Math.random()*2,Math.random()*2-2,['#7d9ed1','#dda74a','#a58ac1'][state.dinoCount%3]);announce('Welcome to your new dino home!');break;case'snack':state.care+=18;state.happy+=2;announce('Nom nom! Your dinos are smiling.');break;case'decorate':state.beauty+=14;state.happy+=3;addParkTree();announce('A little more leafy loveliness!');break;case'comfort':state.facilities++;state.happy+=12;state.development+=4;addStand();announce('Treats for everyone!');break}for(const key of ['happy','care','beauty','development'])state[key]=Math.min(100,state[key]);playSound('purchase');update()}
document.querySelectorAll('.action').forEach(b=>b.addEventListener('click',()=>purchase(b.dataset.action)));document.querySelector('#pauseBtn').addEventListener('click',e=>{state.paused=!state.paused;e.currentTarget.innerHTML=state.paused?'▶ &nbsp;Play':'Ⅱ &nbsp;Pause';announce(state.paused?'Park time paused':'Welcome back, Ranger!');playSound()});document.querySelector('#soundBtn').addEventListener('click',e=>{state.muted=!state.muted;e.currentTarget.textContent=state.muted?'🔇':'🔊';if(!state.muted){startMusic();playSound()}});document.querySelector('#keepPlaying').addEventListener('click',()=>document.querySelector('#win').classList.remove('open'));document.querySelectorAll('.navrow[data-jump]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.navrow').forEach(n=>n.classList.remove('active'));b.classList.add('active');document.querySelector('.bottom-area').scrollIntoView({behavior:'smooth'});if(b.dataset.jump==='habitat')document.querySelector('[data-action="habitat"]').focus();if(b.dataset.jump==='comfort')document.querySelector('[data-action="comfort"]').focus()}));
let seconds=0;setInterval(()=>{if(state.paused)return;seconds++;if(seconds%3===0){const rating=score();state.visitors=Math.max(5,Math.round(8+state.happy*.42+state.facilities*4+state.dinoCount*2));state.profit=Math.max(3,Math.round(state.visitors*(.65+state.happy/100)));state.money+=state.profit;state.day=Math.floor(seconds/18)+1;state.happy=Math.max(15,state.happy-.35+(state.facilities?0.12:0));state.care=Math.max(12,state.care-.46);if(seconds%12===0){state.money+=20;state.fossils++;announce('Park visitors left a little tip! +$20')}if(rating>=40&&seconds%30===0)state.fossils++;update()}},1000);
const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();dinos.forEach((d,i)=>{d.parts[0].position.y=.7+Math.sin(t*2+d.phase)*.055;d.parts[5].rotation.y=Math.sin(t*1.6+d.phase)*.08;d.parts[5].position.x=d.base+1.01+Math.sin(t*1.6+d.phase)*.035;d.parts[0].rotation.y=Math.sin(t*.6+d.phase)*.1});renderer.render(scene,camera)}animate();update();
// Music begins only after the visitor's first interaction, as required by browsers.
document.body.addEventListener('pointerdown',()=>{if(!state.muted)startMusic()},{once:true});

