@@ -3,9 +3,9 @@
 <head>
 <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Fern & Fossil — Dino Park</title>
 <style>
 @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Outfit:wght@500;600;700;800&display=swap');
-:root{--ink:#203b35;--muted:#758b7c;--green:#2d7654;--lime:#d8f06c;--paper:#f8f8ef;--line:#e4e9dc;--orange:#f6a64b}*{box-sizing:border-box}body{margin:0;background:#f4f4e9;color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh}.app{height:100vh;min-height:680px;display:grid;grid-template-columns:276px 1fr;overflow:hidden}.sidebar{background:#fffefa;border-right:1px solid var(--line);padding:24px 18px 18px;display:flex;flex-direction:column;z-index:3}.brand{display:flex;align-items:center;gap:11px;padding:0 6px 23px}.brandmark{width:43px;height:43px;border-radius:15px;background:#dff18c;display:grid;place-items:center;font-size:25px;box-shadow:inset 0 -3px #c8dc72}.brand h1{font:800 19px 'Outfit';margin:0;letter-spacing:-.7px}.brand small{font-size:10px;color:#87988b;letter-spacing:1.6px;font-weight:700;text-transform:uppercase}.parklabel{font-size:10px;font-weight:800;letter-spacing:1.5px;color:#9aa99d;margin:0 8px 11px}.resource{display:flex;align-items:center;gap:11px;background:#f5f7ef;border-radius:14px;padding:12px;margin-bottom:8px}.res-icon{width:36px;height:36px;background:white;border-radius:11px;display:grid;place-items:center;font-size:18px}.res-copy{flex:1}.res-copy span{display:block;color:#87978a;font-size:11px;font-weight:600}.res-copy b{font:700 17px 'Outfit';display:block;margin-top:1px}.res-change{font-size:10px;color:#4f9c68;font-weight:700}.nav{margin:18px 0 7px}.navrow{width:100%;border:0;background:none;text-align:left;padding:11px 12px;border-radius:11px;color:#75877b;font:700 13px 'DM Sans';display:flex;align-items:center;gap:12px;cursor:pointer}.navrow span:first-child{width:22px;font-size:17px;text-align:center}.navrow.active,.navrow:hover{background:#edf5dc;color:#326344}.sidebar-foot{margin-top:auto;background:#f5f7ef;padding:14px;border-radius:15px}.weather{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:700}.weather i{font-style:normal;font-size:22px}.weather small{display:block;color:#91a092;font-size:10